using Microsoft.EntityFrameworkCore; using Rajavasantha.Api.Domain;
namespace Rajavasantha.Api.Infrastructure;
public sealed class AppDbContext(DbContextOptions<AppDbContext> options):DbContext(options) { public DbSet<User> Users=>Set<User>(); public DbSet<Role> Roles=>Set<Role>(); public DbSet<RefreshToken> RefreshTokens=>Set<RefreshToken>(); public DbSet<Project> Projects=>Set<Project>(); public DbSet<Category> Categories=>Set<Category>(); public DbSet<Donation> Donations=>Set<Donation>(); public DbSet<Volunteer> Volunteers=>Set<Volunteer>(); public DbSet<ContactMessage> ContactMessages=>Set<ContactMessage>(); public DbSet<Album> Albums=>Set<Album>(); public DbSet<GalleryItem> Gallery=>Set<GalleryItem>(); public DbSet<ContentItem> Content=>Set<ContentItem>(); public DbSet<Testimonial> Testimonials=>Set<Testimonial>(); public DbSet<Partner> Partners=>Set<Partner>(); public DbSet<Document> Documents=>Set<Document>(); public DbSet<Setting> Settings=>Set<Setting>(); public DbSet<ImpactStatistic> ImpactStatistics=>Set<ImpactStatistic>(); protected override void OnModelCreating(ModelBuilder b){foreach(var t in b.Model.GetEntityTypes().Where(x=>typeof(Entity).IsAssignableFrom(x.ClrType)))b.Entity(t.ClrType).HasQueryFilter(BuildFilter(t.ClrType));b.Entity<User>().HasIndex(x=>x.Email).IsUnique();b.Entity<Role>().HasIndex(x=>x.Name).IsUnique();b.Entity<Project>().HasIndex(x=>x.Slug).IsUnique();b.Entity<Category>().HasIndex(x=>x.Slug).IsUnique();b.Entity<ContentItem>().HasIndex(x=>new{x.Type,x.Slug}).IsUnique();b.Entity<Donation>().Property(x=>x.Amount).HasPrecision(18,2);b.Entity<Project>().Property(x=>x.GoalAmount).HasPrecision(18,2);b.Entity<Project>().Property(x=>x.RaisedAmount).HasPrecision(18,2);b.Entity<User>().HasMany(x=>x.Roles).WithMany(x=>x.Users).UsingEntity(j=>j.ToTable("UserRoles"));} static System.Linq.Expressions.LambdaExpression BuildFilter(Type type){var p=System.Linq.Expressions.Expression.Parameter(type,"e");return System.Linq.Expressions.Expression.Lambda(System.Linq.Expressions.Expression.Equal(System.Linq.Expressions.Expression.Property(p,nameof(Entity.IsDeleted)),System.Linq.Expressions.Expression.Constant(false)),p);} }
